async function optimize(file,w,h,path,info){if(!file||file.size>15e6)return toast('Файл слишком большой');try{const u=URL.createObjectURL(file),im=new Image();im.src=u;await im.decode();const k=Math.min(1,w/im.width,h/im.height),c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(u);let b=await new Promise(r=>c.toBlob(r,'image/webp',.8));if(!b||b.size>file.size)b=file;const data=await new Promise(r=>{const f=new FileReader();f.onload=()=>r(f.result);f.readAsDataURL(b)});set(path,data);set(info,`${format(file.size)} → ${format(b.size)}`);renderAll();toast('Изображение оптимизировано')}catch{toast('Не удалось обработать изображение')}}
